edges = [(1,8),(1,9),(0,10),(0,6),(0,5),(2,11),(3,12),(4,13),(7,14)]
from itertools import combinations
n=15
adj={i:set() for i in range(n)}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)
# check triangle-free
for a,b,c in combinations(range(n),3):
    if b in adj[a] and c in adj[a] and c in adj[b]:
        print("triangle",a,b,c)
# check degree
for i in range(n):
    if len(adj[i])<1: print("deg0",i)
# check bipartite -> 2-colorable
color={}
def bfs(s):
    from collections import deque
    q=deque([s]); color[s]=0
    while q:
        u=q.popleft()
        for v in adj[u]:
            if v not in color:
                color[v]=1-color[u]; q.append(v)
            elif color[v]==color[u]:
                return False
    return True
for i in range(n):
    if i not in color and adj[i]:
        if not bfs(i): print("not bipartite")
print("OK", edges)
